def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    additions = set()

    # Continue each existing diagonal pair of matching non-background cells
    # outward from both ends, stopping at the boundary or another object cell.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != color:
                    continue
                for er, ec, sr, sc in (
                    (r, c, -dr, -dc),
                    (nr, nc, dr, dc),
                ):
                    rr, cc = er + sr, ec + sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        additions.add((rr, cc, color))
                        rr += sr
                        cc += sc

    for r, c, color in additions:
        out[r][c] = color
    return out
